-- Frozen schema version 2 from Corvus commit c23bc5c. Do not regenerate from the current model.
CREATE TABLE "node"("id" INTEGER PRIMARY KEY AUTOINCREMENT,"name" VARCHAR NOT NULL,"host" VARCHAR NOT NULL,"node_agent_port" INTEGER NOT NULL,"net_agent_port" INTEGER NOT NULL,"base_path" VARCHAR NOT NULL,"description" VARCHAR NULL DEFAULT NULL,"admin_state" VARCHAR NOT NULL,"created_at" TIMESTAMP NOT NULL,"cpu_count" INTEGER NULL DEFAULT NULL,"ram_mb_total" INTEGER NULL DEFAULT NULL,"ram_mb_free" INTEGER NULL DEFAULT NULL,"storage_bytes_total" INTEGER NULL DEFAULT NULL,"storage_bytes_free" INTEGER NULL DEFAULT NULL,"load_avg1" REAL NULL DEFAULT NULL,"load_avg5" REAL NULL DEFAULT NULL,"load_avg15" REAL NULL DEFAULT NULL,"kernel_release" VARCHAR NULL DEFAULT NULL,"agent_version" VARCHAR NULL DEFAULT NULL,"node_agent_healthcheck" TIMESTAMP NULL DEFAULT NULL,"net_agent_healthcheck" TIMESTAMP NULL DEFAULT NULL,"netd_disabled" BOOLEAN NOT NULL DEFAULT false,CONSTRAINT "unique_node_name" UNIQUE ("name"),CONSTRAINT "unique_node_address" UNIQUE ("host","node_agent_port"));
CREATE TABLE "vm"("id" INTEGER PRIMARY KEY AUTOINCREMENT,"name" VARCHAR NOT NULL,"node_id" INTEGER NOT NULL REFERENCES "node" ON DELETE RESTRICT ON UPDATE RESTRICT,"created_at" TIMESTAMP NOT NULL,"status" VARCHAR NOT NULL,"cpu_count" INTEGER NOT NULL,"ram_mb" INTEGER NOT NULL,"description" VARCHAR NULL,"headless" BOOLEAN NOT NULL DEFAULT false,"guest_agent" BOOLEAN NOT NULL DEFAULT false,"tpm" BOOLEAN NOT NULL DEFAULT false,"cloud_init" BOOLEAN NOT NULL DEFAULT false,"healthcheck" TIMESTAMP NULL DEFAULT NULL,"autostart" BOOLEAN NOT NULL DEFAULT false,"spice_port" INTEGER NULL DEFAULT NULL,"vsock_cid" INTEGER NULL DEFAULT NULL,"error_message" VARCHAR NULL DEFAULT NULL,"last_error_at" TIMESTAMP NULL DEFAULT NULL,"reboot_quirk" BOOLEAN NOT NULL DEFAULT false,"cpu_model" VARCHAR NOT NULL DEFAULT 'host',CONSTRAINT "unique_vm_name_per_node" UNIQUE ("node_id","name"));
CREATE TABLE "disk_image"("id" INTEGER PRIMARY KEY AUTOINCREMENT,"name" VARCHAR NOT NULL,"format" VARCHAR NOT NULL,"size_mb" INTEGER NULL,"created_at" TIMESTAMP NOT NULL,"backing_image_id" INTEGER NULL REFERENCES "disk_image" ON DELETE RESTRICT ON UPDATE RESTRICT,"ephemeral" BOOLEAN NOT NULL DEFAULT false,CONSTRAINT "unique_disk_image_name" UNIQUE ("name"));
CREATE TABLE "disk_image_node"("id" INTEGER PRIMARY KEY AUTOINCREMENT,"disk_image_id" INTEGER NOT NULL REFERENCES "disk_image" ON DELETE RESTRICT ON UPDATE RESTRICT,"node_id" INTEGER NOT NULL REFERENCES "node" ON DELETE RESTRICT ON UPDATE RESTRICT,"file_path" VARCHAR NOT NULL,CONSTRAINT "unique_disk_image_on_node" UNIQUE ("disk_image_id","node_id"),CONSTRAINT "unique_disk_image_path_per_node" UNIQUE ("node_id","file_path"));
CREATE TABLE "snapshot"("id" INTEGER PRIMARY KEY AUTOINCREMENT,"disk_image_id" INTEGER NOT NULL REFERENCES "disk_image" ON DELETE RESTRICT ON UPDATE RESTRICT,"name" VARCHAR NOT NULL,"created_at" TIMESTAMP NOT NULL,"size_mb" INTEGER NULL,"live" BOOLEAN NOT NULL DEFAULT false,"quiesced" BOOLEAN NOT NULL DEFAULT false,"has_vmstate" BOOLEAN NOT NULL DEFAULT false,CONSTRAINT "unique_snapshot" UNIQUE ("disk_image_id","name"));
CREATE TABLE "drive"("id" INTEGER PRIMARY KEY AUTOINCREMENT,"vm_id" INTEGER NOT NULL REFERENCES "vm" ON DELETE RESTRICT ON UPDATE RESTRICT,"disk_image_id" INTEGER NOT NULL REFERENCES "disk_image" ON DELETE RESTRICT ON UPDATE RESTRICT,"interface" VARCHAR NOT NULL,"media" VARCHAR NULL,"read_only" BOOLEAN NOT NULL DEFAULT false,"cache_type" VARCHAR NOT NULL,"discard" BOOLEAN NOT NULL DEFAULT false,CONSTRAINT "unique_drive" UNIQUE ("vm_id","disk_image_id"));
CREATE TABLE "network"("id" INTEGER PRIMARY KEY AUTOINCREMENT,"name" VARCHAR NOT NULL,"node_id" INTEGER NOT NULL REFERENCES "node" ON DELETE RESTRICT ON UPDATE RESTRICT,"subnet" VARCHAR NOT NULL DEFAULT '',"dhcp" BOOLEAN NOT NULL DEFAULT false,"nat" BOOLEAN NOT NULL DEFAULT false,"running" BOOLEAN NOT NULL DEFAULT false,"dnsmasq_pid" INTEGER NULL,"created_at" TIMESTAMP NOT NULL,"autostart" BOOLEAN NOT NULL DEFAULT false,"vni" INTEGER NULL DEFAULT NULL,"dns_servers" VARCHAR NOT NULL DEFAULT '',"domain" VARCHAR NOT NULL DEFAULT '',"host_dns" BOOLEAN NOT NULL DEFAULT true,CONSTRAINT "unique_network_per_node" UNIQUE ("node_id","name"));
CREATE TABLE "network_peer"("id" INTEGER PRIMARY KEY AUTOINCREMENT,"network_id" INTEGER NOT NULL REFERENCES "network" ON DELETE RESTRICT ON UPDATE RESTRICT,"node_id" INTEGER NOT NULL REFERENCES "node" ON DELETE RESTRICT ON UPDATE RESTRICT,CONSTRAINT "unique_network_peer" UNIQUE ("network_id","node_id"));
CREATE TABLE "network_interface"("id" INTEGER PRIMARY KEY AUTOINCREMENT,"vm_id" INTEGER NOT NULL REFERENCES "vm" ON DELETE RESTRICT ON UPDATE RESTRICT,"interface_type" VARCHAR NOT NULL,"host_device" VARCHAR NOT NULL,"mac_address" VARCHAR NOT NULL,"network_id" INTEGER NULL REFERENCES "network" ON DELETE RESTRICT ON UPDATE RESTRICT,"guest_ip_addresses" VARCHAR NULL DEFAULT NULL,"ip_address" VARCHAR NULL DEFAULT NULL);
CREATE TABLE "shared_dir"("id" INTEGER PRIMARY KEY AUTOINCREMENT,"vm_id" INTEGER NOT NULL REFERENCES "vm" ON DELETE RESTRICT ON UPDATE RESTRICT,"path" VARCHAR NOT NULL,"tag" VARCHAR NOT NULL,"cache" VARCHAR NOT NULL,"read_only" BOOLEAN NOT NULL DEFAULT false,CONSTRAINT "unique_shared_dir_tag" UNIQUE ("vm_id","tag"));
CREATE TABLE "ssh_key"("id" INTEGER PRIMARY KEY AUTOINCREMENT,"name" VARCHAR NOT NULL,"public_key" VARCHAR NOT NULL,"created_at" TIMESTAMP NOT NULL,CONSTRAINT "unique_ssh_key_name" UNIQUE ("name"));
CREATE TABLE "vm_ssh_key"("id" INTEGER PRIMARY KEY AUTOINCREMENT,"vm_id" INTEGER NOT NULL REFERENCES "vm" ON DELETE RESTRICT ON UPDATE RESTRICT,"ssh_key_id" INTEGER NOT NULL REFERENCES "ssh_key" ON DELETE RESTRICT ON UPDATE RESTRICT,CONSTRAINT "unique_vm_ssh_key" UNIQUE ("vm_id","ssh_key_id"));
CREATE TABLE "template_vm"("id" INTEGER PRIMARY KEY AUTOINCREMENT,"name" VARCHAR NOT NULL,"cpu_count" INTEGER NOT NULL,"ram_mb" INTEGER NOT NULL,"description" VARCHAR NULL,"headless" BOOLEAN NOT NULL DEFAULT false,"cloud_init" BOOLEAN NOT NULL DEFAULT false,"guest_agent" BOOLEAN NOT NULL DEFAULT false,"tpm" BOOLEAN NOT NULL DEFAULT false,"autostart" BOOLEAN NOT NULL DEFAULT false,"reboot_quirk" BOOLEAN NOT NULL DEFAULT false,"created_at" TIMESTAMP NOT NULL,CONSTRAINT "unique_template_vm_name" UNIQUE ("name"));
CREATE TABLE "template_drive"("id" INTEGER PRIMARY KEY AUTOINCREMENT,"template_id" INTEGER NOT NULL REFERENCES "template_vm" ON DELETE RESTRICT ON UPDATE RESTRICT,"disk_image_id" INTEGER NULL REFERENCES "disk_image" ON DELETE RESTRICT ON UPDATE RESTRICT,"disk_name" VARCHAR NULL,"interface" VARCHAR NOT NULL,"media" VARCHAR NULL,"read_only" BOOLEAN NOT NULL DEFAULT false,"cache_type" VARCHAR NOT NULL,"discard" BOOLEAN NOT NULL DEFAULT false,"clone_strategy" VARCHAR NOT NULL,"size_mb" INTEGER NULL,"format" VARCHAR NULL,"ephemeral" BOOLEAN NULL);
CREATE TABLE "template_network_interface"("id" INTEGER PRIMARY KEY AUTOINCREMENT,"template_id" INTEGER NOT NULL REFERENCES "template_vm" ON DELETE RESTRICT ON UPDATE RESTRICT,"interface_type" VARCHAR NOT NULL,"host_device" VARCHAR NULL,"network_name" VARCHAR NULL);
CREATE TABLE "template_ssh_key"("id" INTEGER PRIMARY KEY AUTOINCREMENT,"template_id" INTEGER NOT NULL REFERENCES "template_vm" ON DELETE RESTRICT ON UPDATE RESTRICT,"ssh_key_id" INTEGER NOT NULL REFERENCES "ssh_key" ON DELETE RESTRICT ON UPDATE RESTRICT,CONSTRAINT "unique_template_ssh_key" UNIQUE ("template_id","ssh_key_id"));
CREATE TABLE "template_shared_dir"("id" INTEGER PRIMARY KEY AUTOINCREMENT,"template_id" INTEGER NOT NULL REFERENCES "template_vm" ON DELETE RESTRICT ON UPDATE RESTRICT,"path" VARCHAR NOT NULL,"tag" VARCHAR NOT NULL,"cache" VARCHAR NOT NULL,"read_only" BOOLEAN NOT NULL DEFAULT false,CONSTRAINT "unique_template_shared_dir_tag" UNIQUE ("template_id","tag"));
CREATE TABLE "task"("id" INTEGER PRIMARY KEY AUTOINCREMENT,"parent" INTEGER NULL REFERENCES "task" ON DELETE RESTRICT ON UPDATE RESTRICT,"started_at" TIMESTAMP NOT NULL,"finished_at" TIMESTAMP NULL,"subsystem" VARCHAR NOT NULL,"entity_id" INTEGER NULL,"entity_name" VARCHAR NULL,"command" VARCHAR NOT NULL,"result" VARCHAR NOT NULL,"message" VARCHAR NULL,"client_name" VARCHAR NOT NULL);
CREATE TABLE "cloud_init"("id" INTEGER PRIMARY KEY AUTOINCREMENT,"vm_id" INTEGER NOT NULL REFERENCES "vm" ON DELETE RESTRICT ON UPDATE RESTRICT,"user_data" VARCHAR NULL,"network_config" VARCHAR NULL,"inject_ssh_keys" BOOLEAN NOT NULL DEFAULT true,CONSTRAINT "unique_cloud_init_vm" UNIQUE ("vm_id"));
CREATE TABLE "template_cloud_init"("id" INTEGER PRIMARY KEY AUTOINCREMENT,"template_id" INTEGER NOT NULL REFERENCES "template_vm" ON DELETE RESTRICT ON UPDATE RESTRICT,"user_data" VARCHAR NULL,"network_config" VARCHAR NULL,"inject_ssh_keys" BOOLEAN NOT NULL DEFAULT true,CONSTRAINT "unique_template_cloud_init_vm" UNIQUE ("template_id"));
CREATE TABLE "build_cache_entry"("id" INTEGER PRIMARY KEY AUTOINCREMENT,"pipeline_key" VARCHAR NOT NULL,"step_index" INTEGER NOT NULL,"chain_hash" VARCHAR NOT NULL,"disk_role" VARCHAR NOT NULL,"snapshot_id" INTEGER NOT NULL REFERENCES "snapshot" ON DELETE RESTRICT ON UPDATE RESTRICT,"vm_id" INTEGER NOT NULL REFERENCES "vm" ON DELETE RESTRICT ON UPDATE RESTRICT,"created_at" TIMESTAMP NOT NULL,CONSTRAINT "unique_build_cache_chain_disk" UNIQUE ("pipeline_key","chain_hash","disk_role"));
CREATE TABLE schema_version (id INTEGER PRIMARY KEY, version INTEGER NOT NULL);
INSERT INTO schema_version (id, version) VALUES (1, 2);
